package com.dukaops.backend.contact; import java.time.Instant; import java.util.UUID; import com.dukaops.backend.tenant.Tenant; import jakarta.persistence.*;
@Entity @Table(name="suppliers") public class Supplier { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="tenant_id") private Tenant tenant; @Column(name="business_name") private String businessName; @Column(name="contact_person") private String contactPerson; private String phone,email,address,notes; @Enumerated(EnumType.STRING) private ContactStatus status=ContactStatus.ACTIVE; @Column(name="created_at") private Instant createdAt; @Column(name="updated_at") private Instant updatedAt; protected Supplier(){} public Supplier(Tenant t,String b,String c,String p,String e,String a,String n){id=UUID.randomUUID();tenant=t;businessName=b;contactPerson=c;phone=p;email=e;address=a;notes=n;} @PrePersist void create(){createdAt=Instant.now();updatedAt=createdAt;} @PreUpdate void update(){updatedAt=Instant.now();} public UUID getId(){return id;} public Tenant getTenant(){return tenant;} public String getBusinessName(){return businessName;} public String getContactPerson(){return contactPerson;} public String getPhone(){return phone;} public String getEmail(){return email;} public String getAddress(){return address;} public String getNotes(){return notes;} public ContactStatus getStatus(){return status;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public void update(String b,String c,String p,String e,String a,String n){businessName=b;contactPerson=c;phone=p;email=e;address=a;notes=n;} public void setStatus(ContactStatus s){status=s;} }
